-- S20: independent Claude attestation; exact package hash; only AUTO; no legacy mutation.
BEGIN;
DO $s20$
DECLARE p jsonb; e record; h text; val jsonb; ans jsonb; cd text; n int:=0; pub int:=0; links int:=0; b_leg jsonb; b_dep jsonb; lid int; residual text; diff text; old_desc text; new_desc text;
BEGIN
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO b_leg FROM lf_ops.reglas t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones t;
 FOR p IN SELECT value FROM jsonb_array_elements($pack$[{"codigo":"S19-C05","version":2,"eval_id":1212,"hash_version_atestado":"81ddf203e3356bfd7c10caefa7fbc902a8aacac6b8c09e65c635bfdd81334ad2","hash_paquete_atestado":"8bfaa2e103681ed85490579a637ff53abb723ad03320ae13f3644a6a0e2e37c2","hash_evaluado":"81ddf203e3","veredicto":"PASS","juez":"Claude independiente 2026-11-24 17:05 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":179,"familia":"API_DATA_CONTRACT","diferencias":"No acredita endpoints desplegados; contrato de estructura solamente.","residual":"","complementa":null},{"codigo":"S20-C01","version":1,"eval_id":1213,"hash_version_atestado":"9ccf3429a5f7c337a28820f3f7367ff21c29db01796c3ae1fe25e4b68fb5a85f","hash_paquete_atestado":"fa6f685e7da4d8a8f88b8d8d34743e6a92b7fae8f142e74caf7c8b8cc5a80db1","hash_evaluado":"9ccf3429a5","veredicto":"PASS","juez":"Claude independiente 2026-11-24 17:05 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"mismo texto por nodo; aceptable porque el motor aplica un nodo por candidata y los nodos son disjuntos, no solapa con S18-C01 de onboarding"},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":46,"familia":"UI_MESSAGES","diferencias":"Una regla por nodo por limitación de aplicaciones; CLIENT_ONBOARDING cubierto por S18-C01. Cobertura conjunta de S20-C01..C04 y S18-C01.","residual":"","complementa":"S18-C01"},{"codigo":"S20-C02","version":1,"eval_id":1214,"hash_version_atestado":"7a349f0cf13a63fc5e3e865a0e619b5fc1c63039a95505cf8bc44a05816acf29","hash_paquete_atestado":"54c95ebef6805313855a821c03346349cc47cf9e3114f6de0973875fd6119f29","hash_evaluado":"7a349f0cf1","veredicto":"PASS","juez":"Claude independiente 2026-11-24 17:05 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"mismo texto por nodo; aceptable porque el motor aplica un nodo por candidata y los nodos son disjuntos, no solapa con S18-C01 de onboarding"},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":46,"familia":"UI_MESSAGES","diferencias":"Una regla por nodo por limitación de aplicaciones; CLIENT_ONBOARDING cubierto por S18-C01. Cobertura conjunta de S20-C01..C04 y S18-C01.","residual":"","complementa":"S18-C01"},{"codigo":"S20-C03","version":1,"eval_id":1215,"hash_version_atestado":"ed5ceee5d57c27b227caaecf9ad25bd780da72a5b88cb441808b6019ccea90ed","hash_paquete_atestado":"9b5feca8aa741cc28777fdfd4087c2dfbf9f63a77206fb808a2cbe8d94d669c8","hash_evaluado":"ed5ceee5d5","veredicto":"PASS","juez":"Claude independiente 2026-11-24 17:05 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"mismo texto por nodo; aceptable porque el motor aplica un nodo por candidata y los nodos son disjuntos, no solapa con S18-C01 de onboarding"},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":46,"familia":"UI_MESSAGES","diferencias":"Una regla por nodo por limitación de aplicaciones; CLIENT_ONBOARDING cubierto por S18-C01. Cobertura conjunta de S20-C01..C04 y S18-C01.","residual":"","complementa":"S18-C01"},{"codigo":"S20-C04","version":1,"eval_id":1216,"hash_version_atestado":"ff79f8b94eacb1389b2108bc4425950bd748d37659cae8d644cac7f1826ab4f8","hash_paquete_atestado":"48474c184a39e3aa7dfe5d735cd69f1c32900b99c2f64b68ce1863405ec820a8","hash_evaluado":"ff79f8b94e","veredicto":"PASS","juez":"Claude independiente 2026-11-24 17:05 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"mismo texto por nodo; aceptable porque el motor aplica un nodo por candidata y los nodos son disjuntos, no solapa con S18-C01 de onboarding"},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":46,"familia":"UI_MESSAGES","diferencias":"Una regla por nodo por limitación de aplicaciones; CLIENT_ONBOARDING cubierto por S18-C01. Cobertura conjunta de S20-C01..C04 y S18-C01.","residual":"","complementa":"S18-C01"}]$pack$::jsonb) LOOP
 cd:=p->>'codigo'; lid:=(p->>'legada_id')::int;
 SELECT id,regla,version,hash_paquete INTO e FROM lf_ops.nucleo_evaluaciones WHERE regla=cd AND version=(p->>'version')::int ORDER BY id DESC LIMIT 1;
 IF ((SELECT count(*) FROM lf_ops.reglas)=586 AND e.id IS DISTINCT FROM (p->>'eval_id')::bigint) OR left(p->>'hash_version_atestado',10) IS DISTINCT FROM p->>'hash_evaluado' OR e.hash_paquete IS DISTINCT FROM p->>'hash_paquete_atestado' OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=e.version)<>8 OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='CANDIDATA' AND hash=p->>'hash_version_atestado') THEN RAISE EXCEPTION 'S20_ATTESTATION_DRIFT %',cd; END IF;
 h:=lf_ops.nucleo_hash_paquete_v1(cd,e.version);
 IF h IS DISTINCT FROM e.hash_paquete THEN RAISE EXCEPTION 'S20_HASH_DRIFT %',cd; END IF;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto',p->>'veredicto','puntajes',p->'puntajes','juez',p->>'juez','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','sandbox/lf_contract_gate_test/nucleo_ci/nucleo_s20_juicios_5_v1.json#'||cd);
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S20_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision'<>'AUTO' THEN RAISE EXCEPTION 'S20_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado'<>'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S20_PROMOTION_FAIL % %',cd,ans; END IF;
 pub:=pub+1;
 n:=n+1;
 END LOOP;
 IF n<>5 OR pub<>5 THEN RAISE EXCEPTION 'S20_PUBLICATION_INCOMPLETE'; END IF;
 IF (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE estado='PUBLICADA' AND ((regla='S19-C05' AND version=2) OR (regla IN ('S20-C01','S20-C02','S20-C03','S20-C04') AND version=1)))<>5 THEN RAISE EXCEPTION 'S20_GROUP_PUBLICATION_INCOMPLETE'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements($pack$[{"codigo":"S19-C05","version":2,"eval_id":1212,"hash_version_atestado":"81ddf203e3356bfd7c10caefa7fbc902a8aacac6b8c09e65c635bfdd81334ad2","hash_paquete_atestado":"8bfaa2e103681ed85490579a637ff53abb723ad03320ae13f3644a6a0e2e37c2","hash_evaluado":"81ddf203e3","veredicto":"PASS","juez":"Claude independiente 2026-11-24 17:05 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":179,"familia":"API_DATA_CONTRACT","diferencias":"No acredita endpoints desplegados; contrato de estructura solamente.","residual":"","complementa":null},{"codigo":"S20-C01","version":1,"eval_id":1213,"hash_version_atestado":"9ccf3429a5f7c337a28820f3f7367ff21c29db01796c3ae1fe25e4b68fb5a85f","hash_paquete_atestado":"fa6f685e7da4d8a8f88b8d8d34743e6a92b7fae8f142e74caf7c8b8cc5a80db1","hash_evaluado":"9ccf3429a5","veredicto":"PASS","juez":"Claude independiente 2026-11-24 17:05 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"mismo texto por nodo; aceptable porque el motor aplica un nodo por candidata y los nodos son disjuntos, no solapa con S18-C01 de onboarding"},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":46,"familia":"UI_MESSAGES","diferencias":"Una regla por nodo por limitación de aplicaciones; CLIENT_ONBOARDING cubierto por S18-C01. Cobertura conjunta de S20-C01..C04 y S18-C01.","residual":"","complementa":"S18-C01"},{"codigo":"S20-C02","version":1,"eval_id":1214,"hash_version_atestado":"7a349f0cf13a63fc5e3e865a0e619b5fc1c63039a95505cf8bc44a05816acf29","hash_paquete_atestado":"54c95ebef6805313855a821c03346349cc47cf9e3114f6de0973875fd6119f29","hash_evaluado":"7a349f0cf1","veredicto":"PASS","juez":"Claude independiente 2026-11-24 17:05 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"mismo texto por nodo; aceptable porque el motor aplica un nodo por candidata y los nodos son disjuntos, no solapa con S18-C01 de onboarding"},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":46,"familia":"UI_MESSAGES","diferencias":"Una regla por nodo por limitación de aplicaciones; CLIENT_ONBOARDING cubierto por S18-C01. Cobertura conjunta de S20-C01..C04 y S18-C01.","residual":"","complementa":"S18-C01"},{"codigo":"S20-C03","version":1,"eval_id":1215,"hash_version_atestado":"ed5ceee5d57c27b227caaecf9ad25bd780da72a5b88cb441808b6019ccea90ed","hash_paquete_atestado":"9b5feca8aa741cc28777fdfd4087c2dfbf9f63a77206fb808a2cbe8d94d669c8","hash_evaluado":"ed5ceee5d5","veredicto":"PASS","juez":"Claude independiente 2026-11-24 17:05 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"mismo texto por nodo; aceptable porque el motor aplica un nodo por candidata y los nodos son disjuntos, no solapa con S18-C01 de onboarding"},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":46,"familia":"UI_MESSAGES","diferencias":"Una regla por nodo por limitación de aplicaciones; CLIENT_ONBOARDING cubierto por S18-C01. Cobertura conjunta de S20-C01..C04 y S18-C01.","residual":"","complementa":"S18-C01"},{"codigo":"S20-C04","version":1,"eval_id":1216,"hash_version_atestado":"ff79f8b94eacb1389b2108bc4425950bd748d37659cae8d644cac7f1826ab4f8","hash_paquete_atestado":"48474c184a39e3aa7dfe5d735cd69f1c32900b99c2f64b68ce1863405ec820a8","hash_evaluado":"ff79f8b94e","veredicto":"PASS","juez":"Claude independiente 2026-11-24 17:05 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"mismo texto por nodo; aceptable porque el motor aplica un nodo por candidata y los nodos son disjuntos, no solapa con S18-C01 de onboarding"},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":46,"familia":"UI_MESSAGES","diferencias":"Una regla por nodo por limitación de aplicaciones; CLIENT_ONBOARDING cubierto por S18-C01. Cobertura conjunta de S20-C01..C04 y S18-C01.","residual":"","complementa":"S18-C01"}]$pack$::jsonb) LOOP
 cd:=p->>'codigo'; lid:=(p->>'legada_id')::int;
 SELECT (p->>'version')::int AS version INTO e;
 h:=lf_ops.nucleo_hash_paquete_v1(cd,e.version);
 IF h IS DISTINCT FROM p->>'hash_paquete_atestado' THEN RAISE EXCEPTION 'S20_COVERAGE_HASH_DRIFT %',cd; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 IF EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id=lid AND nucleo_codigo=cd AND version_nucleo=e.version) THEN RAISE EXCEPTION 'S20_COVERAGE_DRIFT %',lid; END IF;
 IF p->>'complementa' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada c JOIN lf_ops.nucleo_regla_versiones v ON v.regla=c.nucleo_codigo AND v.version=c.version_nucleo WHERE c.legacy_id=lid AND c.nucleo_codigo=p->>'complementa' AND c.estado_cobertura='PARCIAL' AND v.estado='PUBLICADA') THEN RAISE EXCEPTION 'S20_COMPLEMENT_DRIFT %',lid; END IF;
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 SELECT descripcion INTO new_desc FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version;
 residual:=coalesce(p->>'residual',''); diff:=p->>'diferencias'||CASE WHEN residual<>'' THEN ' Residual: '||residual ELSE '' END;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,e.version,'REEMPLAZADA',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente S20 2026-11-24 17:05','limite_aceptacion','Cobertura funcional; binding runtime no certificado'),h,'GPT / Claude S20 independiente');
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S20_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 IF n<>5 OR pub<>5 OR ((SELECT count(*) FROM lf_ops.reglas)=586 AND links<>5) OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM b_dep THEN RAISE EXCEPTION 'S20_READBACK_FAIL n=% pub=% links=%',n,pub,links; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S20_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S20_PASS 5 JUICIOS 5 AUTO links=% DPIG03=0',links;
END $s20$;
DO $cobertura$
DECLARE n int;
BEGIN
IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=46) THEN
 SELECT count(*) INTO n FROM lf_ops.lf_nucleo_cobertura_legada c JOIN lf_ops.nucleo_regla_versiones v ON v.regla=c.nucleo_codigo AND v.version=c.version_nucleo AND v.estado='PUBLICADA' WHERE c.legacy_id=46 AND c.estado_cobertura IN ('PARCIAL','REEMPLAZADA') AND c.nucleo_codigo IN ('S18-C01','S20-C01','S20-C02','S20-C03','S20-C04');
 IF n<>5 THEN RAISE EXCEPTION 'S20_GROUP_COVERAGE_INCOMPLETE %',n; END IF;
 UPDATE lf_ops.lf_nucleo_cobertura_legada SET estado_cobertura='REEMPLAZADA', diferencias='Cobertura conjunta S18-C01 y S20-C01..C04; una regla por nodo por limitación de aplicaciones; CLIENT_ONBOARDING cubierto por S18-C01.', evidencia=evidencia||jsonb_build_object('residual','','juicio','Claude independiente S20 2026-11-24 17:05','cobertura_conjunta',jsonb_build_array('S18-C01','S20-C01','S20-C02','S20-C03','S20-C04')) WHERE legacy_id=46 AND nucleo_codigo IN ('S18-C01','S20-C01','S20-C02','S20-C03','S20-C04') AND estado_cobertura IN ('PARCIAL','REEMPLAZADA');
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>5 THEN RAISE EXCEPTION 'S20_GROUP_READBACK_FAIL %',n; END IF;
END IF;
IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S20_DPIG03_FAIL'; END IF;
END $cobertura$;
COMMIT;
